package com.cocode.measureapp.geometry.rectangle

import com.cocode.measureapp.geometry.CameraIntrinsics
import com.cocode.measureapp.geometry.Mat3
import com.cocode.measureapp.geometry.Vec2
import com.cocode.measureapp.geometry.frames.CalibrationProvenance
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.acos
import kotlin.math.max

/**
 * Builds a [RectangleCandidate] from validated object corners `[TL, TR, BR, BL]` and the
 * intrinsics of the SAME aligned image frame. Vanishing points at infinity are supported;
 * rejection happens only for invalid input, numeric degeneracy, grazing views, or marking
 * noise that makes the rectified shape unstable.
 */
object PlaneCandidates {
    fun solve(
        corners: List<Vec2>,
        k: CameraIntrinsics,
        provenance: CalibrationProvenance,
        sceneId: String?,
    ): RectangleCandidate {
        fun reject(reason: RectangleRejection, detail: String) =
            RectangleCandidate.Rejected(reason, detail, provenance, sceneId)

        if (corners.size != 4) return reject(RectangleRejection.INVALID_CORNER_COUNT, "expected 4 corners, got ${corners.size}")
        if (!corners.all { it.x.isFinite() && it.y.isFinite() }) {
            return reject(RectangleRejection.NON_FINITE_CORNERS, "corner coordinates must be finite")
        }
        if (!k.isUsable()) return reject(RectangleRejection.INVALID_INTRINSICS, "intrinsics not finite/positive: $k")
        val kInv = k.inverseMatrix()

        val plane = when (val r = VanishingPlane.solve(corners, kInv)) {
            is VanishingPlane.Result.Degenerate -> return reject(r.reason, r.detail)
            is VanishingPlane.Result.Plane -> r
        }
        if (plane.minRayCos < RectangleTolerances.MIN_RAY_PLANE_COS) {
            return reject(RectangleRejection.GRAZING_VIEW, "min ray/normal cosine ${plane.minRayCos}")
        }
        val sensitivity = halfPixelSensitivity(corners, kInv, plane)
        if (!(sensitivity.first <= RectangleTolerances.MAX_HALF_PIXEL_ASPECT_SENSITIVITY)) {
            return reject(RectangleRejection.ILL_CONDITIONED, "half-pixel aspect sensitivity ${sensitivity.first}")
        }
        val evidence = RectangleEvidence(
            widthVanishing = VanishingDirection.classify(plane.widthVp),
            heightVanishing = VanishingDirection.classify(plane.heightVp),
            orthogonalityResidual = plane.orthogonalityResidual,
            minRayPlaneCosine = plane.minRayCos,
            halfPixelAspectSensitivity = sensitivity.first,
            halfPixelNormalShiftRad = sensitivity.second,
        )
        return RectangleCandidate.Accepted(plane.frame, evidence, provenance, sceneId)
    }

    /**
     * Moves each of the 8 corner coordinates by ±[RectangleTolerances.MARK_UNCERTAINTY_PX] and
     * re-solves. Returns (sum over coordinates of the worst relative aspect change, largest
     * normal rotation in radians). A perturbation that collapses the plane gives infinity.
     */
    private fun halfPixelSensitivity(
        corners: List<Vec2>,
        kInv: Mat3,
        base: VanishingPlane.Result.Plane,
    ): Pair<Double, Double> {
        var aspectSum = 0.0
        var normalShift = 0.0
        for (i in corners.indices) for (axis in 0..1) {
            var worst = 0.0
            for (sign in listOf(-1.0, 1.0)) {
                val d = sign * RectangleTolerances.MARK_UNCERTAINTY_PX
                val moved = corners.toMutableList()
                moved[i] = if (axis == 0) Vec2(corners[i].x + d, corners[i].y) else Vec2(corners[i].x, corners[i].y + d)
                val p = VanishingPlane.solve(moved, kInv) as? VanishingPlane.Result.Plane
                    ?: return Pair(Double.POSITIVE_INFINITY, PI)
                worst = max(worst, abs(p.aspect - base.aspect) / base.aspect)
                normalShift = max(normalShift, acos(p.frame.normal.dot(base.frame.normal).coerceIn(-1.0, 1.0)))
            }
            aspectSum += worst
        }
        return Pair(aspectSum, normalShift)
    }
}

package com.cocode.measureapp.geometry.rectangle

import com.cocode.measureapp.geometry.Mat3
import com.cocode.measureapp.geometry.PlaneFrame
import com.cocode.measureapp.geometry.Projective
import com.cocode.measureapp.geometry.Tolerances
import com.cocode.measureapp.geometry.Vec2
import com.cocode.measureapp.geometry.Vec3
import kotlin.math.abs
import kotlin.math.sqrt

/**
 * Plane frame from the two homogeneous vanishing points of a `[TL, TR, BR, BL]` quad.
 *
 * Each vanishing point is back-projected as `K⁻¹ · v` on the raw homogeneous vector, so a
 * point at infinity (`w = 0`, image-parallel edges) yields its direction exactly and passes
 * continuously into nearby finite points. Only numeric degeneracy is rejected here.
 */
internal object VanishingPlane {
    sealed interface Result {
        data class Plane(
            val frame: PlaneFrame,
            val widthVp: Vec3,
            val heightVp: Vec3,
            val orthogonalityResidual: Double,
            val minRayCos: Double,
            val aspect: Double,
        ) : Result

        data class Degenerate(val reason: RectangleRejection, val detail: String) : Result
    }

    fun solve(corners: List<Vec2>, kInv: Mat3): Result {
        val (tl, tr, br, bl) = corners
        val edges = listOf(tl to tr, bl to br, tl to bl, tr to br).map { (a, b) ->
            unitLine(a, b) ?: return degenerate(RectangleRejection.COINCIDENT_CORNERS, "edge $a-$b has no length")
        }
        val widthVp = Projective.homogeneousIntersection(edges[0], edges[1])
        val heightVp = Projective.homogeneousIntersection(edges[2], edges[3])
        if (widthVp.norm() <= RectangleTolerances.ZERO_HOMOGENEOUS || heightVp.norm() <= RectangleTolerances.ZERO_HOMOGENEOUS) {
            return degenerate(RectangleRejection.ZERO_VANISHING_VECTOR, "opposite edges lie on one image line")
        }
        val d1 = (kInv * widthVp).normalized()
        val d2 = (kInv * heightVp).normalized()
        val cross = d1.cross(d2)
        if (cross.norm() <= RectangleTolerances.MIN_DIRECTION_SIN) {
            return degenerate(RectangleRejection.COINCIDENT_DIRECTIONS, "edge directions coincide")
        }

        val rays = corners.map { (kInv * Vec3(it.x, it.y, 1.0)).normalized() }
        var normal = cross.normalized()
        if (normal.dot(rays.reduce { a, b -> a + b }) < 0.0) normal = normal * -1.0
        val cosines = rays.map { normal.dot(it) }
        val minCos = cosines.minOf { it }
        if (!(minCos > Tolerances.PROJ_EPS)) {
            return degenerate(RectangleRejection.PROJECTION_UNUSABLE, "corner rays straddle the plane (min cos $minCos)")
        }
        // Points on the plane `normal · X = 1`; orient e1 along TL->TR, e2 completes the triad.
        val pts = rays.indices.map { rays[it] * (1.0 / cosines[it]) }
        val span = (pts[1] - pts[0]) + (pts[2] - pts[3])
        val e1 = if (d1.dot(span) < 0.0) d1 * -1.0 else d1
        val frame = PlaneFrame(e1, normal.cross(e1).normalized(), normal)
        val aspect = aspect(pts, frame)
        if (!finite(frame) || !(aspect.isFinite() && aspect > 0.0)) {
            return degenerate(RectangleRejection.NUMERICAL_FAILURE, "non-finite plane frame or aspect")
        }
        return Result.Plane(frame, widthVp, heightVp, abs(d1.dot(d2)), minCos, aspect)
    }

    /** Unit homogeneous line through two points, or null when the points coincide. */
    private fun unitLine(a: Vec2, b: Vec2): Vec3? {
        val l = Projective.lineThrough(a, b)
        val scale = sqrt(a.x * a.x + a.y * a.y + 1.0) * sqrt(b.x * b.x + b.y * b.y + 1.0)
        val n = l.norm()
        return if (n <= RectangleTolerances.ZERO_HOMOGENEOUS * scale) null else l * (1.0 / n)
    }

    /** Rectified (top + bottom) / (left + right) edge-length ratio in plane coordinates. */
    private fun aspect(pts: List<Vec3>, frame: PlaneFrame): Double {
        val q = pts.map { Vec2(frame.e1.dot(it), frame.e2.dot(it)) }
        val width = q[1].distanceTo(q[0]) + q[2].distanceTo(q[3])
        val height = q[3].distanceTo(q[0]) + q[2].distanceTo(q[1])
        return width / height
    }

    private fun finite(f: PlaneFrame): Boolean =
        listOf(f.e1, f.e2, f.normal).all { it.x.isFinite() && it.y.isFinite() && it.z.isFinite() }

    private fun degenerate(reason: RectangleRejection, detail: String) = Result.Degenerate(reason, detail)
}

package com.cocode.measureapp.geometry.rectangle

import com.cocode.measureapp.geometry.MeasurementFailureReason
import com.cocode.measureapp.geometry.PlaneFrame
import com.cocode.measureapp.geometry.Vec2
import com.cocode.measureapp.geometry.Vec3
import com.cocode.measureapp.geometry.frames.CalibrationProvenance
import kotlin.math.abs
import kotlin.math.hypot

/**
 * A vanishing point kept in homogeneous image form. A point at infinity is a valid direction
 * (image-parallel edges), never a failure; only the zero vector is degenerate.
 */
sealed interface VanishingDirection {
    /** Homogeneous image point `(x, y, w)`; `w == 0` means at infinity. */
    val homogeneous: Vec3

    data class Finite(override val homogeneous: Vec3, val point: Vec2) : VanishingDirection
    data class AtInfinity(override val homogeneous: Vec3, val imageDirection: Vec2) : VanishingDirection

    companion object {
        /** Labels a nonzero homogeneous point; used for evidence only, never for computation. */
        fun classify(v: Vec3): VanishingDirection {
            val planar = hypot(v.x, v.y)
            return if (abs(v.z) <= RectangleTolerances.INFINITY_RELATIVE * planar) {
                AtInfinity(v, Vec2(v.x / planar, v.y / planar))
            } else {
                Finite(v, Vec2(v.x / v.z, v.y / v.z))
            }
        }
    }
}

/** Why no plane candidate exists, mapped onto the shared failure vocabulary. */
enum class RectangleRejection(val failure: MeasurementFailureReason) {
    INVALID_CORNER_COUNT(MeasurementFailureReason.INVALID_OBJECT_CORNERS),
    NON_FINITE_CORNERS(MeasurementFailureReason.INVALID_OBJECT_CORNERS),
    INVALID_INTRINSICS(MeasurementFailureReason.METADATA_UNAVAILABLE),

    /** An edge's endpoints coincide, so it defines no line. */
    COINCIDENT_CORNERS(MeasurementFailureReason.INVALID_OBJECT_CORNERS),

    /** Two opposite edges lie on one image line: their intersection is the zero vector. */
    ZERO_VANISHING_VECTOR(MeasurementFailureReason.INVALID_OBJECT_CORNERS),

    /** Both edge pairs back-project to the same direction; no plane is spanned. */
    COINCIDENT_DIRECTIONS(MeasurementFailureReason.UNSUPPORTED_GEOMETRY),

    /** A corner ray is parallel to, or on the far side of, the recovered plane. */
    PROJECTION_UNUSABLE(MeasurementFailureReason.UNSUPPORTED_GEOMETRY),

    /** Corner rays graze the plane (see [RectangleTolerances.MIN_RAY_PLANE_COS]). */
    GRAZING_VIEW(MeasurementFailureReason.UNSUPPORTED_GEOMETRY),

    /** Half-pixel marking noise changes the rectified shape too much. */
    ILL_CONDITIONED(MeasurementFailureReason.UNSUPPORTED_GEOMETRY),

    NUMERICAL_FAILURE(MeasurementFailureReason.NUMERICAL_FAILURE),
}

/**
 * Evidence a selector needs to judge a rectangle candidate. None of it proves the target is a
 * rectangle or that the plane matches the chosen wall/floor surface.
 *
 * @property orthogonalityResidual `|d1 · d2|` of the unit back-projected edge directions;
 *   0 for a true rectangle with exact intrinsics. Scale-independent.
 * @property minRayPlaneCosine smallest `|normal · ray|` over the four unit corner rays.
 * @property halfPixelAspectSensitivity worst-case relative aspect-ratio change under
 *   [RectangleTolerances.MARK_UNCERTAINTY_PX] marking noise (sum over 8 coordinates).
 * @property halfPixelNormalShiftRad largest normal rotation under the same perturbations.
 */
data class RectangleEvidence(
    val widthVanishing: VanishingDirection,
    val heightVanishing: VanishingDirection,
    val orthogonalityResidual: Double,
    val minRayPlaneCosine: Double,
    val halfPixelAspectSensitivity: Double,
    val halfPixelNormalShiftRad: Double,
)

/**
 * Outcome of the rectangle solver for one aligned scene. Both variants carry the calibration
 * [provenance] and the caller's [sceneId] so a candidate cannot be applied to another input.
 */
sealed interface RectangleCandidate {
    val provenance: CalibrationProvenance
    val sceneId: String?

    /** A finite orthonormal plane frame plus its evidence; still subject to eligibility rules. */
    data class Accepted(
        val frame: PlaneFrame,
        val evidence: RectangleEvidence,
        override val provenance: CalibrationProvenance,
        override val sceneId: String?,
    ) : RectangleCandidate

    /** No usable plane; [reason] is explicit and must not be revived with a confidence. */
    data class Rejected(
        val reason: RectangleRejection,
        val detail: String,
        override val provenance: CalibrationProvenance,
        override val sceneId: String?,
    ) : RectangleCandidate
}

package com.cocode.measureapp.geometry

/** Pinhole camera intrinsics, in pixels. */
data class CameraIntrinsics(
    val fx: Double,
    val fy: Double,
    val cx: Double,
    val cy: Double,
) {
    fun matrix() = Mat3(
        fx, 0.0, cx,
        0.0, fy, cy,
        0.0, 0.0, 1.0,
    )

    fun inverseMatrix() = matrix().inverse()

    /** Finite positive focal lengths and a finite principal point: safe to back-project with. */
    fun isUsable(): Boolean =
        fx.isFinite() && fy.isFinite() && fx > 0.0 && fy > 0.0 && cx.isFinite() && cy.isFinite()
}

package com.cocode.measureapp.geometry

import kotlin.math.sqrt

data class Vec2(val x: Double, val y: Double) {
    operator fun plus(o: Vec2) = Vec2(x + o.x, y + o.y)
    operator fun minus(o: Vec2) = Vec2(x - o.x, y - o.y)
    operator fun times(s: Double) = Vec2(x * s, y * s)
    fun dot(o: Vec2) = x * o.x + y * o.y
    fun norm() = sqrt(x * x + y * y)
    fun normalized(): Vec2 {
        val n = norm()
        require(n > Tolerances.NORM_EPS) { "cannot normalize zero-length vector" }
        return Vec2(x / n, y / n)
    }
    fun distanceTo(o: Vec2) = (this - o).norm()
}

data class Vec3(val x: Double, val y: Double, val z: Double) {
    operator fun plus(o: Vec3) = Vec3(x + o.x, y + o.y, z + o.z)
    operator fun minus(o: Vec3) = Vec3(x - o.x, y - o.y, z - o.z)
    operator fun times(s: Double) = Vec3(x * s, y * s, z * s)
    fun dot(o: Vec3) = x * o.x + y * o.y + z * o.z
    fun cross(o: Vec3) = Vec3(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x)
    fun norm() = sqrt(x * x + y * y + z * z)
    fun normalized(): Vec3 {
        val n = norm()
        require(n > Tolerances.NORM_EPS) { "cannot normalize zero-length vector" }
        return Vec3(x / n, y / n, z / n)
    }
}

package com.cocode.measureapp.geometry

/** Numeric guards shared across the geometry primitives. */
object Tolerances {
    /** Unit-scale guard for normalization / matrix invertibility. */
    const val NORM_EPS = 1e-12

    /** Image-scale guard for parallel lines / projective degeneracy. */
    const val PROJ_EPS = 1e-9

    /*
     * Marker quadrilateral degeneracy guards. They apply to marks in the canonical
     * image-pixel frame (never display/screen pixels) and are DIMENSIONLESS: each compares a
     * quantity against the quad's own diameter (largest vertex-to-vertex distance), so any
     * uniform scaling — display zoom, pan, or image resolution — yields the same outcome.
     */

    /** Minimum vertex separation as a fraction of the quad diameter (covers every edge). */
    const val MARKER_MIN_SEPARATION_FRACTION = 1e-3

    /** Minimum |sin| of the turn at every vertex; below it three vertices are collinear. */
    const val MARKER_MIN_TURN_SIN = 1e-3

    /** Minimum enclosed area as a fraction of the squared quad diameter. */
    const val MARKER_MIN_AREA_FRACTION = 1e-4
}

